package com.hljzjx.classroom.reviewdraw;
import java.util.*;
import com.hljzjx.classroom.reviewdraw.InkQueue.*;
public final class InkQueueTest {
 static int checks;
 static void ok(boolean x,String message){checks++;if(!x)throw new AssertionError(message);}
 static final Key A=new Key(7,10,20,30),B=new Key(7,10,20,31);
 static Stroke s(String id,String v){return new Stroke(id,v,false);}
 static final class Job implements Comparable<Job>{long at;int seq;Runnable r;public int compareTo(Job j){int n=Long.compare(at,j.at);return n!=0?n:Integer.compare(seq,j.seq);}}
 static final class Clock implements Scheduler {long now,uid=7;int seq;PriorityQueue<Job> jobs=new PriorityQueue<Job>();public long user(){return uid;}public void post(Runnable r,long delay){Job j=new Job();j.at=now+delay;j.seq=seq++;j.r=r;jobs.add(j);}void tick(long n){long end=now+n;int loops=0;while(!jobs.isEmpty()&&jobs.peek().at<=end){ok(loops++<3000,"no runaway scheduling");Job j=jobs.remove();now=j.at;j.r.run();}now=end;}}
 static final class Request<T>{Key key;List<Stroke> batch;Callback<T> callback;void done(T v,String e){callback.done(v,e);}}
 static final class Net implements Transport {List<Request<Boolean>> sends=new ArrayList<Request<Boolean>>();List<Request<List<Stroke>>> reads=new ArrayList<Request<List<Stroke>>>();public void append(Key k,List<Stroke> b,Callback<Boolean> c){Request<Boolean> r=new Request<Boolean>();r.key=k;r.batch=b;r.callback=c;sends.add(r);}public void read(Key k,Callback<List<Stroke>> c){Request<List<Stroke>> r=new Request<List<Stroke>>();r.key=k;r.callback=c;reads.add(r);}}
 static final class Disk implements Store {Map<Key,Snapshot> values=new HashMap<Key,Snapshot>();public Snapshot load(Key k){return values.get(k);}public void save(Key k,Snapshot s){values.put(k,s);}}
 static final class F {Clock c=new Clock();Net n=new Net();Disk disk=new Disk();InkQueue q=new InkQueue(c,n,disk,new Listener(){public void changed(Key k){}});void ack(int i,boolean value){n.sends.get(i).done(value,value?null:"reject");c.tick(0);}void read(int i,Stroke...strokes){n.reads.get(i).done(Arrays.asList(strokes),null);c.tick(0);}List<Stroke> overlay(Key k){return q.overlay(k,Collections.<Stroke>emptyList());}}
 static void cadence(){F f=new F();f.q.put(A,s("1","one"));f.c.tick(1999);ok(f.n.sends.isEmpty(),"two second debounce");f.q.put(A,s("2","two"));f.c.tick(1999);ok(f.n.sends.isEmpty(),"reset stop-pen debounce");f.c.tick(1);ok(f.n.sends.size()==1&&f.n.sends.get(0).batch.size()==2,"batch own deltas");f.ack(0,true);ok(f.q.status(A).contains("回读"),"readback runs");f.read(0);ok(f.q.status(A).contains("尚未回读"),"cache acceptance is not DB confirmation");ok(f.overlay(A).size()==2,"accepted drafts visible");f.q.read(A,null);f.read(1,s("1","one"),s("2","two"));ok(f.q.status(A).contains("回读确认"),"true confirmation");ok(f.disk.values.get(A).pending.isEmpty()&&f.disk.values.get(A).accepted.isEmpty(),"persisted queue drained");}
 static void groups(){F f=new F();f.q.put(A,s("1","A"));f.q.put(B,s("1","B"));f.c.tick(2000);ok(f.n.sends.size()==2,"both groups upload");ok(f.n.sends.get(0).key.equals(A)&&f.n.sends.get(0).batch.get(0).value.equals("A"),"group A frozen");ok(f.n.sends.get(1).key.equals(B)&&f.n.sends.get(1).batch.get(0).value.equals("B"),"group B frozen");f.ack(0,true);f.read(0);ok(f.overlay(B).get(0).value.equals("B"),"A read does not erase B");}
 static void edits(){F f=new F();f.q.put(A,s("1","old"));f.c.tick(2000);f.q.put(A,s("1","new"));f.ack(0,true);ok(f.n.sends.size()==2,"new version follows successful old upload");ok(f.n.sends.get(1).batch.get(0).value.equals("new"),"immutable old batch");f.q.read(A,null);f.read(0,s("1","old"));ok(f.overlay(A).get(0).value.equals("new"),"old read cannot remove new edit");f.ack(1,true);f.read(1,s("1","new"));ok(f.q.status(A).contains("回读确认"),"latest version confirmed");f.n.sends.get(0).done(false,"duplicate");f.c.tick(0);ok(f.q.status(A).contains("回读确认"),"duplicate callback ignored");}
 static void rejected(){F f=new F();f.q.put(A,s("1","one"));f.c.tick(2000);f.ack(0,false);ok(f.q.status(A).equals("reject"),"business failure surfaced");ok(f.overlay(A).size()==1,"failure retains ink");f.c.tick(100000);ok(f.n.sends.size()==1,"no unbounded business-failure retry");f.q.retry(A);ok(f.n.sends.size()==2,"explicit retry");f.ack(1,true);f.read(0,s("1","one"));ok(f.q.status(A).contains("回读确认"),"retry success");}
 static void timeout(){F f=new F();f.q.put(A,s("1","one"));f.c.tick(32000);ok(f.n.reads.size()==1,"timeout reads before resending");f.read(0);ok(f.q.status(A).contains("待确认"),"ambiguous upload visible");f.c.tick(100000);ok(f.n.sends.size()==1,"unknown batch does not loop");f.q.retry(A);ok(f.n.sends.size()==2,"unknown upload can be retried");f.ack(1,true);f.read(1,s("1","one"));f.n.sends.get(0).done(true,null);f.c.tick(0);ok(f.q.status(A).contains("回读确认"),"late ACK cannot resurrect already-confirmed draft");}
 static void lateWithNewer(){F f=new F();f.q.put(A,s("1","old"));f.c.tick(32000);f.read(0);f.q.put(A,s("1","new"));f.q.retry(A);f.ack(1,true);f.read(1,s("1","new"));f.n.sends.get(0).done(true,null);f.c.tick(0);ok(f.q.status(A).contains("回读确认"),"late obsolete ack cannot shadow new version");ok(f.overlay(A).isEmpty(),"obsolete draft not overlaid");}
 static void lateFailureAfterAcceptance(){F f=new F();f.q.put(A,s("1","one"));f.c.tick(32000);f.read(0);f.q.retry(A);f.ack(1,true);f.read(1);f.n.sends.get(0).done(false,"old rejection");f.c.tick(0);ok(f.q.status(A).contains("尚未回读"),"old rejection cannot undo newer server acceptance");}
 static void accounts(){F f=new F();f.q.put(A,s("1","one"));f.c.uid=8;f.c.tick(2000);ok(f.n.sends.isEmpty(),"account switched before debounce");f.q.retry(A);ok(f.n.sends.isEmpty(),"manual retry cannot send another user's data");f.q.put(A,s("2","two"));ok(f.overlay(A).size()==1,"wrong account mutation refused");f.c.uid=7;f.q.retry(A);ok(f.n.sends.size()==1,"original account can resume own queue");f.c.uid=8;f.ack(0,true);ok(f.n.reads.isEmpty(),"old account ACK does not cause authenticated read as new user");}
 static void restart(){F f=new F();f.q.put(A,s("1","one"));InkQueue restart=new InkQueue(f.c,f.n,f.disk,new Listener(){public void changed(Key k){}});ok(restart.overlay(A,Collections.<Stroke>emptyList()).size()==1,"restart keeps unsent draft");restart.retry(A);ok(f.n.sends.size()==1,"restored queue can upload");}
 static void inFlightRestart(){F f=new F();f.q.put(A,s("1","one"));f.c.tick(2000);ok(f.disk.values.get(A).unknown.size()==1,"in-flight request persisted as uncertain");Clock clock=new Clock();Net net=new Net();InkQueue restart=new InkQueue(clock,net,f.disk,new Listener(){public void changed(Key k){}});restart.read(A,null);net.reads.get(0).done(Collections.<Stroke>emptyList(),null);clock.tick(0);ok(net.sends.isEmpty()&&restart.status(A).contains("待确认"),"restart cannot silently duplicate an in-flight request");}
 static void tombstone(){F f=new F();Stroke deleted=new Stroke("7_1","delete",true);f.q.put(A,deleted);ok(f.overlay(A).isEmpty(),"eraser tombstone invisible");f.q.read(A,null);f.read(0);ok(f.disk.values.get(A).pending.size()==1,"absence before upload is not delete confirmation");f.c.tick(2000);ok(f.n.sends.get(0).batch.get(0).deleted,"delete sent in native form");f.ack(0,true);f.read(1,deleted);ok(f.q.status(A).contains("回读确认"),"delete confirmed by readback");}
 static void readRaces(){F f=new F();final int[] calls={0};Callback<List<Stroke>> cb=new Callback<List<Stroke>>(){public void done(List<Stroke> s,String e){calls[0]++;}};f.q.read(A,cb);f.read(0,s("1","one"));f.n.reads.get(0).done(Collections.<Stroke>emptyList(),null);f.c.tick(0);ok(calls[0]==1,"duplicate read completion ignored");f.q.read(A,cb);f.c.tick(30000);ok(calls[0]==2&&f.q.status(A).contains("超时"),"read timeout delivered");f.read(1,s("2","late"));ok(calls[0]==2,"late read does not call UI twice");}
 static void coalescedRead(){F f=new F();final int[] calls={0},readbacks={0};InkQueue q=new InkQueue(f.c,f.n,f.disk,new ReadListener(){public void changed(Key k){}public void readback(Key k,List<Stroke> strokes){readbacks[0]++;}});Callback<List<Stroke>> cb=new Callback<List<Stroke>>(){public void done(List<Stroke> value,String error){calls[0]++;}};q.read(A,cb);q.read(A,cb);q.read(A,null);ok(f.n.reads.size()==1,"concurrent GET requests coalesce");f.n.reads.get(0).done(Collections.<Stroke>emptyList(),null);f.c.tick(0);ok(calls[0]==2&&readbacks[0]==1,"all UI waiters complete once");q.read(A,cb);f.n.reads.get(0).done(Arrays.asList(s("1","stale")),null);f.c.tick(0);ok(readbacks[0]==1,"late old read cannot notify current UI");f.n.reads.get(1).done(Collections.<Stroke>emptyList(),null);f.c.tick(0);ok(calls[0]==3&&readbacks[0]==2,"new read remains valid");}
 static void passiveReads(){F f=new F();f.q.put(A,s("1","one"));f.q.observe(A,null);f.read(0);f.c.tick(1999);ok(f.n.sends.isEmpty(),"observation does not accelerate debounce");f.c.tick(1);f.ack(0,false);f.q.observe(A,null);f.read(1);f.c.tick(5000);ok(f.n.sends.size()==1&&f.q.status(A).equals("reject"),"passive GET never retries rejected writes or clears their error");f.q.observe(A,null);f.n.reads.get(2).done(null,"read failed");f.c.tick(0);ok(f.q.status(A).equals("reject"),"observation failure preserves upload error");f.q.observe(A,null);f.c.tick(30000);ok(f.q.status(A).equals("reject"),"passive timeout preserves upload error");f.q.retry(A);ok(f.n.sends.size()==2,"explicit write retry still works");}
 static void passiveUpgrade(){F f=new F();f.q.put(A,s("1","one"));f.q.observe(A,null);f.q.read(A,null);ok(f.n.reads.size()==1,"active read coalesces with observation");f.read(0);ok(f.n.sends.size()==1,"active read upgrades restore semantics");}
 static void batching(){F f=new F();for(int i=0;i<260;i++)f.q.put(A,s("7_"+i,"v"+i));f.c.tick(2000);ok(f.n.sends.get(0).batch.size()==128,"bounded first batch");f.ack(0,true);ok(f.n.sends.get(1).batch.size()==128,"bounded next batch");f.ack(1,true);ok(f.n.sends.get(2).batch.size()==4,"final batch");Set<String> ids=new HashSet<String>();for(Request<Boolean> r:f.n.sends)for(Stroke x:r.batch)ok(ids.add(x.id),"no duplicate IDs across batches");ok(ids.size()==260,"all deltas queued");}
 public static void main(String[] args){cadence();groups();edits();rejected();timeout();lateWithNewer();lateFailureAfterAcceptance();accounts();restart();inFlightRestart();tombstone();readRaces();coalescedRead();passiveReads();passiveUpgrade();batching();System.out.println("PASS InkQueue: "+checks+" assertions; no network/device used");}
}
